 top:readerT,bottom:readerB,
 keys:[['▲/▼','A few lines',null],['◀/▶','A screen back / on (L, R and A too)',null],['L2/R2','Previous / next chapter',null],['Y','Contents and bookmarks','reader-contents'],['SELECT','Text: how the page looks','reader-view'],['X','More: Add bookmark, Find…, Book mode, Encoding, Info, Show in folder',null],['L3','Find',null],['B','Close (your place is kept)','books'],['START','Menu','menu'],['F','Quick settings','quick']],
