// ---------- added: a song's four Show modes; the visualizer alone ----------
const songInfo=()=>`<div class="ab in" style="left:22px;top:18px;right:22px;text-shadow:0 2px 0 #000,0 0 8px #000"><div style="font-weight:600;font-size:26px;color:#fff">Sunny Peel</div><div style="font-size:17px;color:#e8e2d3;margin-top:5px">The Plantains</div><div style="font-size:14px;color:#aba597;margin-top:3px">Yellow Album</div></div>`;
function city(){let s=5,o='';for(let i=0;i<16;i++){s=(s*9301+49297)%233280;const r=s/233280,h=90+Math.round(r*210),lit=Math.round(20+r*70);o+=`<div style="flex:1;height:${h}px;background:repeating-linear-gradient(90deg,transparent 0 5px,#11152a 5px 11px),repeating-linear-gradient(0deg,#11152a 0 8px,rgba(255,210,63,${(lit/100).toFixed(2)}) 8px 15px);border-top:3px solid #2a3158;box-shadow:inset 0 0 0 2px #11152a"></div>`}
	return `<div class="ab" style="inset:0;background:radial-gradient(circle at 80% 18%,#f6f0d2 0 3.5%,transparent 4%),linear-gradient(#070a1c,#1a2350 70%,#3a2f63)"></div><div class="ab" style="left:0;right:0;bottom:0;display:flex;gap:4px;align-items:flex-end;padding:0 10px">${o}</div>`}
const artBox=(sz,noart)=>`<div class="sc-art" style="width:${sz}px;height:${sz}px;flex:none;border-radius:8px;box-shadow:0 0 0 2px #26242e;display:grid;place-items:center">${noart?`<span style="width:${sz*.38}px;height:${sz*.38}px;border-radius:${sz*.08}px;background:rgba(0,0,0,.62);display:grid;place-items:center;color:#fff">${ico('music',Math.round(sz*.22))}</span>`:''}</div>`;
// the art and its text are one group, centred as a group on its real width (the text is as wide as its longest line, capped), in the space given
const artGroup=(sz,top,bottom,info,title='Sunny Peel',noart)=>`<div class="ab" style="left:40px;right:40px;top:${top}px;bottom:${bottom}px;display:flex;align-items:center;justify-content:center;gap:28px">${artBox(sz,noart)}${info?`<div class="in" style="min-width:0;max-width:${560-sz-28}px"><div style="font-weight:600;font-size:28px;line-height:1.2;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${title}</div><div style="font-size:17px;color:#e8e2d3;margin-top:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">The Plantains</div><div style="font-size:14px;color:#aba597;margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">Yellow Album · 2026</div></div>`:''}</div>`;
const musicTop=(mode,info,style='peaks',title,noart)=>`<div class="ab" style="inset:0;background:#000"></div>`+
	(mode=='art'?artGroup(info?240:260,0,0,info,title,noart):'')+
	(mode=='artviz'?artGroup(info?224:240,16,176,info,title,noart)+`<div class="ab" style="left:24px;right:24px;bottom:14px">${peaks(52,124)}</div>`:'')+
	(mode=='viz'?(style=='city'?city():`<div class="ab" style="inset:0;background:repeating-linear-gradient(0deg,rgba(255,255,255,.055) 0 1px,transparent 1px 40px),repeating-linear-gradient(90deg,rgba(255,255,255,.035) 0 1px,transparent 1px 40px)"></div><div class="ab" style="left:20px;right:20px;bottom:20px">${peaks(64,340,23)}</div>`)+(info?songInfo():''):'')+
	(mode=='none'?`<div class="ab in" style="left:0;right:0;top:196px;text-align:center"><div style="font-weight:600;font-size:30px;color:#fff">Sunny Peel</div><div style="font-size:17px;color:#aba597;margin-top:8px">The Plantains · Yellow Album</div></div>`:'');
const STYLES=['Peaks','Circle','Pocket console','Night city','Banana dancer','Campfire','Aurora','Sound garden','Pixel sea','Bunny hop','Bubble tea','Jellyfish','Music box','Fishbowl','Vibing cat','Popcorn','Jelly wobble','Tube man','Long cat','Washing machine'];
const MTABS=['Display','Visualizer','Equalizer','Effects','Speed'];
const SHOWN=['Album art','Art + visualizer','Visualizer','Title only'];
const displaySheet=(show,style,info)=>sheet(300,`<div class="sh">${tabs(MTABS,0,{1:'music-viz-pick',2:'music-eq'})}</div>
	<div class="gl" style="margin:2px 0 6px">Show · SELECT steps through</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px">${[['photo','music-view'],['viz','music-view'],['viz','music-viz'],['text','']].map((t,i)=>`<div class="btn ${i==show?'acc':''}" ${t[1]&&i!=show?`data-go="${t[1]}"`:''} style="height:52px;font-size:14px;gap:6px">${ico(t[0],16)}${SHOWN[i]}</div>`).join('')}</div>
	<div class="row" data-go="music-viz-pick" style="height:46px;margin-top:8px;font-size:15px">${ico('viz',20)}<span class="nm">Visualizer</span><span class="nt">${STYLES[style]}${show==0||show==3?' · not shown':''}</span>${ico('chevR',14,'color:var(--dm)')}</div>
	<div class="row" style="height:46px;font-size:15px"><span class="nm">Song info on top</span><span class="nt">Title, artist, album on the top screen</span><i class="sw ${info?'on':''}"></i></div>`,[['D-pad','Change'],['SELECT','Next Show'],['L/R','Tab'],['B','Close']]);
const vizSheet=(show,style)=>{const hid=show==0||show==3;return sheet(hid?384:318,`<div class="sh">${tabs(MTABS,1,{0:'music-view',2:'music-eq'})}</div>
	${hid?`<div class="btn flat notice two" style="margin-bottom:8px">${ico('info',20)}<div style="flex:1;text-align:left;min-width:0"><div style="font-size:15px">Not on the top screen now</div><div class="in dm" style="font-size:12px;margin-top:4px">Show is ${SHOWN[show]}. Your choice is kept.</div></div><div class="btn" style="height:44px;padding:0 12px;font-size:15px;flex:none;gap:6px">Show it${cap('Y')}</div></div>`:''}
	<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px">${STYLES.map((t,i)=>`<div class="btn flat ${i==style?'foc':''}" style="height:46px;font-size:13px;border-radius:8px;${i==style?'color:var(--ac)':''}">${t}</div>`).join('')}</div>`,hid?[['D-pad','Choose'],['Y','Show it'],['L/R','Tab'],['SELECT/B','Close']]:[['D-pad','Choose'],['L/R','Tab'],['SELECT/B','Close']])};
const mini=(t,cap)=>`<figure><div class="panel"><div class="s">${t}</div></div><figcaption><b>${cap[0]}</b> ${cap[1]}</figcaption></figure>`;
{const mv=SCREENS.find(s=>s.id=='music-view');
 mv.bottom=()=>musicB()+displaySheet(1,0,1);
 mv.keys=[['D-pad','Move over Show, Visualizer and Song info: the top screen follows Show',null],['A','On Visualizer: its tab, the twenty styles','music-viz-pick'],['SELECT','The next Show mode: Album art → Art + visualizer → Visualizer → Title only','music-viz'],['R','Next tab: Visualizer','music-viz-pick'],['B','Close','music']];
 mv.notes=[['chg','The Display popup becomes two tabs of View, one for each choice. Display: Show, what the top screen shows. Visualizer: which style. Sound’s Equalizer and Effects tabs join them.'],['chg','Show and the style are two choices and are never written as one. The Top screen chip says Show only. The style is named on the Visualizer row here, on its own tab, and in Settings.'],['new','The Visualizer row names the style in use and opens its tab. With Album art or Title only it reads “Peaks · not shown”: the choice is kept and can still be changed; it is not dimmed, because nothing is unavailable.'],['same','Four Show modes, as today: Album art (the default), Art + visualizer, Visualizer, and None, here named for what it shows: Title only.'],['chg','The art’s layout changes from today’s app. Today the art is scaled to the full 480 height and the visualizer is laid over its bottom. Here the art is smaller and never covered: in Art + visualizer the bars run in a band along the bottom of the screen, under the art.'],['chg','Song info on top, with art: switched off (the default) the art is alone, centred. Switched on, the art moves to the left and the title, artist and album sit to its right, the pair centred as a group on its real width (a short title does not leave it hugging the left; equal margins of 40 units), the text centred on the art’s middle; nothing is ever written over the art. A long title is cut with “…”. Over a visualizer alone the info stays top left, as today.'],['chg','A song with no art (none in the file, no cover.jpg): the placeholder, the colour wheel with a note on it, stands in the art’s spot in both art modes, same layout. Today the app falls back instead: Album art becomes the title alone, Art + visualizer becomes the visualizer alone. Here the mode you chose is the mode you see.'],['same','SELECT opens it and SELECT again steps to the next Show mode, as in today’s popup; B closes. (The one sheet where the opening key does not close it.)'],['mov','Song info on top: a switch here as well as in Settings (today Settings only), since this is where you are looking at the top screen.'],['same','The visualizer’s frame rate stays in Settings › Music & sound, unmarked: see State indicators.']];
 mv.extra=()=>`<div class="eyebrow" style="margin-top:16px">The top screen in each Show mode</div><div class="minis">${mini(musicTop('art',0),['Album art','Song info off (default): the art alone, 260 units, centred'])}${mini(musicTop('art',1),['Album art','Song info on: art left, info right'])}${mini(musicTop('artviz',0),['Art + visualizer','info off: the art centred above the band of bars'])}${mini(musicTop('artviz',1),['Art + visualizer','info on: art left, info right, bars under'])}${mini(musicTop('viz',0),['Visualizer','alone'])}${mini(musicTop('none',0),['Title only','(today: None)'])}${mini(musicTop('artviz',1,'peaks','The Long Way Round the Banana Grove (Live)'),['A long title','cut with “…”, never under the art'])}${mini(musicTop('artviz',1,'peaks',undefined,1),['No art in the file','the placeholder takes the art’s spot; the layout does not change'])}${mini(musicTop('viz',1,'city'),['Visualizer','Night city + Song info'])}</div>`;}
