// ---------- added: volume past 100%; playing in a browser ----------
const vcard=(p,label='Volume',max=150,pos='right:20px;top:20px')=>{const col=p>120?'var(--dg)':p>100?'var(--ac)':'var(--tx)';return `<div class="tcard" style="${pos};width:290px"><div class="fx" style="gap:10px;font-size:19px;color:${col}">${ico('speaker',20)}${label}<span style="flex:1"></span>${p}%</div><div style="position:relative;height:8px;border-radius:4px;background:var(--bt);margin-top:12px"><i class="ab" style="left:0;top:0;bottom:0;width:${Math.min(p,100)/max*100}%;background:var(--tx);border-radius:4px ${p>100?'0 0':'4px 4px'} 4px"></i>${p>100?`<i class="ab" style="left:${100/max*100}%;top:0;bottom:0;width:${(Math.min(p,120)-100)/max*100}%;background:var(--ac)"></i>`:''}${p>120?`<i class="ab" style="left:${120/max*100}%;top:0;bottom:0;width:${(p-120)/max*100}%;background:var(--dg)"></i>`:''}${max>100?`<b class="ab" style="left:${100/max*100}%;top:-5px;width:2px;height:18px;background:var(--do)"></b>`:''}</div>${max>100?`<div class="in" style="font-size:12px;margin-top:9px;color:${p>100?col:'var(--dm)'}">${p>120?'Very loud: can harm hearing and the speakers':p>100?'Boosted · Volume − takes it off first':'The mark is 100%, the handheld’s own top'}</div>`:''}</div>`};
const bTop=(t,sub,hint,pct=34)=>`<div class="ab" style="inset:0;background:#0b0a0d"></div><div class="ab col" style="left:40px;right:40px;top:104px;align-items:center;text-align:center"><div style="width:72px;height:72px;border-radius:18px;background:var(--sf);border:2px solid var(--eds);display:grid;place-items:center;color:var(--ac)">${ico('globe',34)}</div><div style="font-size:29px;color:var(--ac);margin-top:16px">${t}</div><div class="in" style="font-size:16px;color:var(--tx);margin-top:9px">${sub}</div>${pct==null?'':`<div class="bar" style="width:300px;margin-top:16px;height:6px;background:var(--bt)"><i style="width:${pct}%"></i></div><div class="in dm" style="font-size:13px;margin-top:8px">1:12 / 3:34 · the browser’s time</div>`}<div class="in fx" style="gap:8px;font-size:14px;color:var(--do);margin-top:18px">${hint}</div></div>`;
const dchip=(ic,l,v,w=146)=>schip(ic,l,v,'','',w,1);
const holdKey=(pct,l='Pause')=>`<div class="btn acc" style="position:relative;overflow:hidden;width:176px;height:74px;flex-direction:column;gap:3px">${pct?`<i class="ab" style="left:0;top:0;bottom:0;width:${pct}%;background:rgba(0,0,0,.28)"></i>`:''}<span style="position:relative">${ico('pause',22)}</span><span class="fx" style="gap:6px;font-size:14px;position:relative">${l}${cap('A')}</span><span class="in" style="font-size:12px;font-weight:600;position:relative">${pct?'Keep holding…':'Hold: play it here'}</span></div>`;
const bsong=(o={})=>player({back:'browser-mini',srcIcon:'playlist',crumb:'Playlist · Late night',pos:'3 / 9',more:'play-on',title:'Sunny Peel',st:o.st||{browser:'Chrome'},
	state:o.state||`<span class="fx ac" style="gap:6px;font-size:15px;white-space:nowrap">${ico('globe',16)}In Chrome on Mac</span>`,
	line:`<div class="sc-art" style="width:30px;height:30px;border-radius:5px;flex:none"></div><span style="font-size:14px;color:var(--tx)">The Plantains</span><span>·</span><span>Yellow Album · 2026</span>`,
	pct:34,cur:'1:12',left:'2:22',tot:'3:34',list:'',view:'',mid:o.mid||holdKey(o.hold||0),
	chips:o.chips||[dchip('eq','Sound','Handheld only'),dchip('viz','Top screen','Handheld only'),schip('speed','Speed','1×',''),schip('shuffle','Shuffle','On','','on')],
	nextIcon:'music',next:'Green at the Tips',nextNote:'4:02 · shuffled',hint:o.hint||[['A','Pause there'],['Hold A','Play here'],['L/R','Song'],['X','More · Play on'],['B','Back']]});
