// ---------- added: the coverage batch (states, errors, dialogs, tools, network, the Manga app, settings groups) ----------
const tInfo=(tk,title,text,rows=[],hint=[],red)=>`<div class="ab" style="inset:0;background:#000"></div>${tBrand()}<div class="ab" style="left:44px;right:44px;top:74px"><div class="tk" style="${red?'color:var(--dg)':''}">${tk}</div><div style="font-size:28px;margin:8px 0 8px;line-height:1.15">${title}</div><div class="in" style="font-size:14.5px;color:var(--do);line-height:1.5">${text}</div>${rows.length?`<dl class="tmeta" style="margin:18px 0 0;font-size:13.5px">${rows.map(r=>`<dt>${r[0]}</dt><dd>${r[1]}</dd>`).join('')}</dl>`:''}${hint.length?`<div style="margin-top:18px">${tHint(hint)}</div>`:''}</div>`;
const alertS=(t,x,ok='OK',red)=>sheet(226,`<div class="sh">${ico('info',20,`color:var(--${red?'dg':'ac'})`)}<h2 style="flex:1;${red?'color:var(--dg)':''}">${t}</h2></div><div class="in" style="font-size:14px;line-height:1.5;padding:0 2px;min-height:44px">${x}</div><div class="btn acc" style="height:56px;margin-top:14px;font-size:17px">${ok}${cap('A')}</div>`,[['A/B','Close']]);
const askS=(h,ic,t,x,safe,act,red,foot='')=>sheet(h,`<div class="sh">${ico(ic,20,`color:var(--${red?'dg':'ac'})`)}<h2 style="flex:1;${red?'color:var(--dg)':''}">${t}</h2></div><div class="in" style="font-size:14px;line-height:1.5;padding:0 2px">${x}</div>${foot}<div class="fx" style="gap:10px;margin-top:16px"><div class="btn acc" style="flex:1;height:56px;font-size:17px">${safe}${cap('B')}</div><div class="btn" style="flex:1;height:56px;font-size:17px;${red?'color:var(--dg)':''}">${act}</div></div>`,[['◀/▶','Choose'],['A','OK'],['B',safe]]);
const busyS=(t,x,pct)=>sheet(214,`<div class="sh">${spin(22).replace('border:5px','border:4px')}<h2 style="flex:1">${t}</h2></div><div class="in" style="font-size:14px;line-height:1.5;padding:0 2px">${x}</div>${pct!=null?`<div class="bar" style="height:12px;border-radius:6px;margin:12px 2px 0"><i style="width:${pct}%"></i></div>`:''}<div class="btn" style="height:56px;margin-top:14px;font-size:17px">Cancel${cap('B')}</div>`,[['B','Cancel']]);
const toast=(t,sub='',ic='',red='')=>`<div class="tcard" style="left:50%;transform:translateX(-50%);bottom:26px;padding:12px 18px;white-space:nowrap;text-align:center">${`<div class="fx" style="gap:10px;font-size:19px;color:var(--${red?'dg':'ac'});justify-content:center">${ic?ico(ic,20):''}${t}</div>`}${sub?`<div class="in" style="font-size:13px;color:var(--do);margin-top:6px">${sub}</div>`:''}</div>`;
const vtable=(head,rows)=>`<div class="tw" style="margin-top:14px"><table><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</table></div>`;
const tick=(on)=>`<i style="width:22px;height:22px;border-radius:6px;border:2px solid ${on?'var(--ac)':'var(--ed)'};background:${on?'var(--ac)':'transparent'};display:grid;place-items:center;color:#000;flex:none">${on?ico('check',16):''}</i>`;
const frow=(l,v,foc)=>`<div class="row ${foc?'foc':''}" style="height:46px"><span style="width:150px;${foc?'color:var(--ac)':'color:var(--do)'}">${l}</span><span class="nm">${v}</span></div>`;
const kbd=(title,crumb,val,specials,back='files',go='')=>`<div class="hd" style="height:54px;padding:0 10px"><div class="btn bk" data-go="${back}">${ico('chevL',20)}</div><div class="tt"><h1 style="font-size:19px">${title}</h1><p class="in">${crumb}</p></div>${status()}</div>
	<div class="ab fx" style="left:12px;right:12px;top:58px;height:48px;border-radius:8px;background:var(--sf);border:2px solid var(--ac);padding:0 12px;font-size:17px;white-space:nowrap;overflow:hidden">${val}<span style="width:2px;height:24px;background:var(--ac);margin-left:2px"></span></div>
	<div class="ab" style="left:12px;right:12px;top:114px;display:grid;grid-template-columns:repeat(10,1fr);gap:5px">${'qwertyuiopasdfghjkl-zxcvbnm,._'.split('').map(k=>`<div class="btn ${k=='g'?'foc':''}" style="height:52px;font-size:19px;border-radius:6px">${k}</div>`).join('')}</div>
	<div class="ab fx" style="left:12px;right:12px;top:290px;gap:5px">${specials.map(([k,w,c],i)=>`<div class="btn ${i==specials.length-1?'acc':''}" ${i==specials.length-1&&go?`data-go="${go}"`:''} style="height:56px;font-size:15px;border-radius:6px;${w?`width:${w}px`:'flex:1'}">${k}${c?cap(c):''}</div>`).join('')}</div>
	${hints([['D-pad','Move'],['A','Type'],['X','⌫'],['Y','Space'],['L3','ABC'],['START','Done'],['B','Cancel']])}`;
const SPEC=[['ABC',70,'L3'],['123',70],['Space',0,'Y'],['⌫',84,'X'],['Done',110,'START']];
const setGroup=(o)=>({id:o.id,group:'Settings groups',name:'Settings › '+o.name,why:o.why,
 top:()=>o.top?o.top():tInfo('Settings › '+o.name,o.focus,o.help,o.dl||[]),
 bottom:()=>shell('settings',{title:o.name,back:'settings',crumb:`Settings · ${o.n} of 12`,more:false,right:`<span class="fx in dm" style="gap:5px;font-size:12px;margin-right:4px;white-space:nowrap">${cap('L2')}Group${cap('R2')}</span>`,body:o.rows.map(r=>srow(r[0],typeof r[1]=='string'&&r[1][0]!='<'?step(r[1]):r[1],r[0]==o.focus?'foc':'')).join('')+(o.foot||''),hint:[['▲/▼','Choose'],['◀/▶','Change'],['L2/R2','Group'],['B','Back']]}),
 keys:[['▲/▼','Choose a row',null],['◀/▶','Change it',null],['L2/R2','The group before / after',null],['B','Back to the groups','settings']],notes:o.notes});
const swv=(on)=>`<i class="sw ${on?'on':''}"></i>`;
const act=(t,red)=>`<span class="nt" style="${red?'color:var(--dg)':''}">${t}</span>${ico('chevR',14,'color:var(--dm)')}`;
const seriesB=()=>shell('manga',{title:'Moonlit Courier',crumb:'Public domain comics · 24 chapters · 2 unread · Checked 7 h ago',back:'manga',more:'',body:`<div class="fx" style="gap:8px"><div class="btn acc" data-go="manga-read" style="width:150px;height:56px;font-size:16px">${ico('play',14)}Resume${cap('A')}</div><div class="btn" data-go="manga-dl" style="flex:1;height:56px;font-size:15px">${ico('download',18)}Get${cap('R2')}</div><div class="btn" style="flex:1;height:56px;font-size:15px">${ico('refresh',18)}Check${cap('L2')}</div><div class="btn" style="width:64px;height:56px">${ico('info',20)}</div><div class="btn" style="width:64px;height:56px;color:var(--ac)">${ico('heart-f',20)}</div></div><div style="height:8px"></div>
	${[['Ch. 24 · The Lighthouse','<span class="pill n">Queued</span>','',1],['Ch. 23 · Low Tide','<span class="pill">12 / 40</span>','p. 3',0,1],['Ch. 22 · The Ferry','<span class="pill n">Paused · 8 / 36</span>',''],['Ch. 21 · Lamp Oil','<span class="pill r">Failed · A retries</span>',''],['Ch. 20 · Night Mail',`<span class="pill n">${ico('check',12)}On card</span>`,'read',0,0,1]].map(r=>`<div class="row ${r[4]?'foc':''}" style="${r[5]?'opacity:.6':''}">${r[3]?'<i style="width:8px;height:8px;border-radius:4px;background:var(--ac)"></i>':'<i style="width:8px"></i>'}<span class="nm">${r[0]}</span>${r[1]}${r[2]?`<span class="nt">${r[2]}</span>`:''}</div>`).join('')}`,hint:[['A','Read'],['Y','Select'],['X','More'],['L2/R2','Check / Get'],['B','Back']]});
